import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.BM_-pWjS.js";const i="/bridge-lite/manual/assets/comp.BMNDFmJE.png",u=JSON.parse('{"title":"Compare","description":"","frontmatter":{},"headers":[],"relativePath":"en/compare.md","filePath":"en/compare.md"}'),s={name:"en/compare.md"};function n(l,e,d,h,p,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="compare" tabindex="-1">Compare <a class="header-anchor" href="#compare" aria-label="Permalink to &quot;Compare&quot;">​</a></h1><p><img src="'+i+'" alt="Compare view"></p><p>bridge-lite treats the camera JPEG, RAW, and developed file from the same shutter press as <strong>one group</strong>. Each individual file within a group — the camera JPEG, the RAW, and the developed variant — is called a <strong>member</strong>.</p><h2 id="why-compare-all-three" tabindex="-1">Why compare all three <a class="header-anchor" href="#why-compare-all-three" aria-label="Permalink to &quot;Why compare all three&quot;">​</a></h2><p>Sometimes the camera&#39;s output is simply better. Sometimes heavy processing makes you lose track of the original. Switching between all three gives you a clear ground truth before you decide which to keep.</p><h2 id="switching-photos" tabindex="-1">Switching Photos <a class="header-anchor" href="#switching-photos" aria-label="Permalink to &quot;Switching Photos&quot;">​</a></h2><p>Arrow keys and <code>Ctrl + Tab</code> can be toggled between group-level and member-level navigation.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>After toggling [Group / Member]</th></tr></thead><tbody><tr><td>← / → / ↑ / ↓</td><td>Move between groups</td><td>Move between members</td></tr><tr><td>Ctrl + Tab / Ctrl + Shift + Tab</td><td>Move between members</td><td>Move between groups</td></tr></tbody></table><p>Clicking <strong>[Group / Member]</strong> at the top of the screen reverses these two behaviors.</p><h2 id="image-only-mode" tabindex="-1">Image Only mode <a class="header-anchor" href="#image-only-mode" aria-label="Permalink to &quot;Image Only mode&quot;">​</a></h2><p>Clicking <strong>[Image Only]</strong> excludes RAW files from the group, so you can compare the camera JPEG and developed file directly.</p><p>RAW previews are rendered on-the-fly by Apple&#39;s rendering engine and do not reflect the actual developed output. Excluding RAW lets you compare the images that will actually be exported, side by side.</p><h2 id="how-pairing-works" tabindex="-1">How pairing works <a class="header-anchor" href="#how-pairing-works" aria-label="Permalink to &quot;How pairing works&quot;">​</a></h2><p>RAW and JPG files are automatically paired in this order:</p><ol><li><strong>Stem name</strong> — <code>DSC04867.ARW</code> and <code>DSC04867.JPG</code> share the same stem</li><li><strong>EXIF timestamp</strong> — Files shot at the same time, even with different names</li><li><strong>pHash</strong> — Perceptual hash for visual similarity</li></ol><p>Files without EXIF data, or shots with very similar compositions, may be incorrectly paired.</p><h2 id="what-counts-as-developed" tabindex="-1">What counts as &quot;developed&quot; <a class="header-anchor" href="#what-counts-as-developed" aria-label="Permalink to &quot;What counts as &quot;developed&quot;&quot;">​</a></h2><p>A JPEG or TIFF exported from Lightroom (or any editor) with the same stem name in the same folder is automatically recognized as a developed variant.</p><p>Files without EXIF data, or shots with very similar compositions, may be incorrectly paired. In particular, if EXIF has been intentionally stripped before delivery, pairing relies on pHash alone, which increases the risk of mismatches between visually similar shots from different exposures.</p>',19)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
